 async function request(path:string,value:unknown){const r=await fetch(`/api/${path}?workspace=${workspace.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});const b=await r.json();if(!r.ok)throw new Error(b.error??'Could not complete this action');return b;}
 async function payOnline(item:BusinessItem){await run(async()=>{if(item.currency!=='USD')throw new Error('Paynow online checkout is currently enabled for USD invoices.');const b=await request('payments/paynow/initiate',{invoice_id:item.id});if(!b.redirect_url)throw new Error('Paynow did not return a checkout link.');window.location.assign(b.redirect_url);});}
 async function startOmari(item:BusinessItem){await run(async()=>{const b=await request('payments/omari/auth',{invoice_id:item.id,msisdn:omari.msisdn});setOmari(o=>({...o,show:true,session_id:b.session_id,otp_reference:b.otp_reference,otp:''}));setMessage('Omari OTP requested. Reference: '+b.otp_reference);});}
 async function confirmOmari(item:BusinessItem){await run(async()=>{const b=await request('payments/omari/request',{session_id:omari.session_id,otp:omari.otp});if(b.invoice)updateItem(b.invoice);setPaper(b.invoice??item);setOmari(o=>({...o,show:false,otp:'',session_id:'',otp_reference:''}));setMessage('Omari payment confirmed and invoice updated.');});}
 async function run(fn:()=>Promise<void>){setBusy(true);setError('');try{await fn();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 function updateItem(item:BusinessItem){setBiz(b=>({...b,items:b.items.some(i=>i.id===item.id)?b.items.map(i=>i.id===item.id?item:i):[item,...b.items]}));if(paper?.id===item.id)setPaper(item);}
 async function workflow(p:RecordRow,action:string){await run(async()=>{let next;if(demo){let status=p.status;if(action==='submit')status='manager_review';if(action==='approve')status=p.status==='manager_review'&&p.client_id?'client_review':'approved';if(action==='reject')status='changes_requested';if(action==='revise')status='draft';next={...p,status,client_visible:action==='revise'?false:status==='client_review'?true:p.client_visible};}else next=await request('social',{id:p.id,action});setData(d=>({...d,social_posts:d.social_posts.map(r=>r.id===p.id?next:r)}));setMessage(action==='approve'?'Approval saved.':'Content workflow updated.');});}
 async function status(m:Module,r:RecordRow,value:string){await run(async()=>{let next={...r,status:value};if(!demo){const res=await fetch(`/api/records/${m}?workspace=${workspace.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:r.id,status:value})});next=await res.json();if(!res.ok)throw new Error((next as any).error);}setData(d=>({...d,[m]:d[m].map(x=>x.id===r.id?next:x)}));});}
 async function save(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!form)return;const f=new FormData(e.currentTarget),kind=form;await run(async()=>{
 const str=(n:string)=>String(f.get(n)??''),num=(n:string)=>Number(f.get(n)??0),ci=client?clientId:str('client_id')||null;
 if(core.includes(kind as Module)){
 const m=kind as Module;
 const value={title:m==='deals'?(ci?clientName(ci):'CRM Opportunity'):str('title'),status:m==='social_posts'?'draft':m==='documents'?(client||f.get('client_visible')?'shared':'internal'):str('status')||statuses[m][0],...(m==='clients'?{email:str('email')}:{client_id:ci,client_visible:client||f.get('client_visible')==='on',description:str('description')}),...(['projects','tasks','social_posts'].includes(m)?{due_date:str('due_date')||null}:{}),...(m==='deals'?{amount:num('amount'),currency:'USD'}:{}),...(m==='social_posts'?{channel:str('channel')}:{})};
 let next:RecordRow;
 if(demo)next={id:crypto.randomUUID(),tenant_id:'demo',client_id:ci,client_visible:false,created_at:new Date().toISOString(),...value};
 else if(m==='documents'){
 const file=f.get('file');if(!(file instanceof File)||!fileMime(file.name)||file.size===0||file.size>maxFileBytes)throw Error('Choose a supported file up to 50 MB.');
 next=await request('documents',{name:file.name,bytes:file.size,title:str('title'),client_id:ci,client_visible:client||f.get('client_visible')==='on'});
 const db=createBrowserClient(process.env.NEXT_PUBLIC_SUPABASE_URL!,process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!);
 const uploaded=await db.storage.from('workspace-documents').upload(next.object_path!,file,{contentType:fileMime(file.name)!,upsert:false});
 if(uploaded.error){await db.from('documents').delete().eq('id',next.id);throw Error('File upload failed. Please retry.');}
 }
 else next=await request(`records/${m}`,value);
 setData(d=>({...d,[m]:[next,...d[m]]}));if(m==='social_posts')setDetail({module:m,row:next});
 }else{
 const payload:Record<string,any>=kind==='quote'||kind==='invoice'?{lines,tax_rate:num('tax_rate'),recurrence:str('recurrence')||'none',...(kind==='invoice'?{payment_terms:str('payment_terms')||'full_payment'}:{})}:kind==='payroll'?{employee:str('title'),base:num('base'),allowances:num('allowances'),overtime:num('overtime'),allowable_deductions:num('allowable_deductions'),tax_credit:num('tax_credit'),other_deductions:num('other_deductions'),period_start:str('period_start'),period_end:str('period_end'),paid_from:str('paid_from'),paid_to:str('paid_to'),pay_date:str('due_date'),frequency:str('frequency'),proration_basis:str('proration_basis'),proration_note:str('proration_note'),request_id:str('request_id'),...(str('proration_basis')==='manual_units'?{paid_units:num('paid_units'),period_units:num('period_units')}:{})}:kind==='sms'?{message:str('description'),audience:str('audience'),purpose:str('purpose')}:{description:str('description')};
 const value={kind,title:str('title'),client_id:ci,currency:str('currency')||'USD',due_date:str('due_date')||null,payload};
 if(demo){
 if(kind==='payroll')throw new Error('Payroll calculation requires verified rules in the connected database. Demo mode does not generate statutory pay calculations.');
 const subtotal=lines.reduce((s,l)=>s+Math.round(l.quantity*l.unit_price*100)/100,0),tax=Math.round(subtotal*num('tax_rate'))/100;
 const created={...value,id:crypto.randomUUID(),tenant_id:'demo',kind:kind as BusinessKind,status:kind==='request'?'open':kind==='invoice'?'issued':'draft',total:['quote','invoice'].includes(kind)?subtotal+tax:0,paid:0,reference:'NXT-DEMO-'+Date.now().toString().slice(-6),created_at:new Date().toISOString(),payload:{...payload,subtotal,tax}} as BusinessItem;
 updateItem(created);if(kind==='invoice')setPaper(created);
 }else{const created=await request('business',value);updateItem(created);if(kind==='invoice')setPaper(created);}
 }
 setForm(null);setMessage(kind==='invoice'?'Invoice saved and issued to the client portal.':demo?'Saved for this demo session. Refresh resets changes.':'Saved to your workspace.');
 });}
 async function act(item:BusinessItem,action:string,extra:Record<string,unknown>={}){await run(async()=>{
 if(demo){if(action==='payment'){const amt=Number(extra.amount);if(!Number.isFinite(amt)||amt<=0||amt>Number(item.total)-Number(item.paid))throw new Error('Enter an amount within the outstanding balance');if(!String(extra.reference??'').trim())throw new Error('Add a payment reference');if(biz.payments.some(p=>p.invoice_id===item.id&&p.reference===extra.reference))throw new Error('This reference has already been recorded');setBiz(b=>({...b,payments:[...b.payments,{id:crypto.randomUUID(),invoice_id:item.id,amount:amt,reference:String(extra.reference),payment_method:extra.payment_method==='cash'?'cash':'bank',created_at:new Date().toISOString()}]}));updateItem({...item,paid:Number(item.paid)+amt,status:Number(item.paid)+amt===Number(item.total)?'paid':'issued'});}else if(action==='convert'){const old=biz.items.find(i=>i.parent_id===item.id&&i.kind==='invoice');if(old){setPaper(old);return;}const converted={...item,id:crypto.randomUUID(),reference:'NXT-DEMO-'+Date.now().toString().slice(-6),kind:'invoice' as const,status:'issued',parent_id:item.id,payload:{...item.payload,payment_terms:item.payload.payment_terms||'full_payment'}};updateItem(converted);setPaper(converted);}else if(action==='recur'){throw new Error('Recurring draft generation is available in the connected workspace.');}else updateItem({...item,status:action==='issue'?'issued':action==='close'?'closed':'finalised'});
 }else{updateItem(await request('business',{id:item.id,action,...extra}));if(action==='payment'){setMessage('Payment recorded. Refresh to load the persisted receipt.');return;}}
 setMessage('Updated successfully.');
 });}
 async function removeTestInvoice(item:BusinessItem){
  const reason=window.prompt('Delete this test invoice from active views? Any issued ledger entry will be reversed. Payments and fiscal invoices cannot be removed. Enter the reason:','Test invoice');
  if(!reason)return;
  await run(async()=>{if(demo)throw Error('Test invoice removal is available in the connected workspace.');const removed=await request('business',{action:'remove_test_invoice',id:item.id,reason});updateItem(removed);setPaper(null);setMessage('Test invoice removed from active views. Accounting history retained.');});
 }
 async function download(r:RecordRow){await run(async()=>{if(demo){setMessage('Connect Supabase to upload and download real files.');return;}const res=await fetch(`/api/documents?workspace=${workspace.id}&id=${r.id}`);const b=await res.json();if(!res.ok)throw new Error(b.error);window.location.assign(b.url);});}
